1	//! Pure extraction for one Rust file.
2	//!
3	//! The parse owns its syntax tree. Everything leaving this module is owned data, so no tree node escapes.
4	
5	use camino::Utf8Path;
6	use ra_ap_syntax::ast::{self, AstNode, HasAttrs, HasModuleItem, HasName, HasVisibility};
7	use ra_ap_syntax::{Edition, NodeOrToken, SourceFile, SyntaxKind, SyntaxNode, TextRange};
8	
9	use crate::analysis::nesting::{self, Syntax};
10	use crate::analysis::parse_stack::on_parse_stack;
11	use crate::analysis::{AnalysisProfile, Degradation};
12	use crate::types::{CodeBlock, ParentContext, SymbolEntry, SymbolKind, Visibility};
13	
14	/// The fewest lines an `impl` or trait method needs to get a block of its own. A shorter one is a stub or accessor
15	/// that the block holding it already shows whole.
16	const MIN_MEMBER_LINES: usize = 3;
17	
18	/// The longest source that is parsed. Parse time and memory grow with the length, not with the stack, so this is chosen
19	/// from measurements of a whole `monokl search` over one generated file: at 4 MB it takes 181 ms and peaks at 151 MB of
20	/// resident memory, about 37 bytes per source byte.
21	pub(super) const MAX_PARSED_SOURCE_LEN: usize = 4 << 20;
22	
23	/// The deepest nesting parsed, in levels of brackets or the equivalent in other nesting (see [`nesting::peak_cost`]).
24	///
25	/// `ra_ap_syntax` hands a finished tree to a shared background thread to drop, one with the default 2 MiB stack, and a
26	/// drop recurses once per level of the tree. That overflows at 4,320 levels in a build without optimizations (485 bytes
27	/// a level) and 26,240 optimized, and overflowing aborts the process. A level of the tree costs at least one unit, and
28	/// a unit is a quarter of a level here, so the 1,024 units of the cap bound the tree. Generic arguments are the deepest
29	/// per unit, at 1.3 tree levels; the tests build 32 nestings at the cap and a fuzzer builds thousands more, and none is
30	/// over 2,150 levels, half of what the unoptimized drop holds. The parser's time is quadratic in
31	/// the depth, so the cap also bounds a worst-case parse to milliseconds.
32	pub(crate) const MAX_NESTING_LEVELS: usize = 256;
33	
34	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
35	#[derive(Debug, Default)]
36	pub(super) struct Extraction {
37	    pub(super) symbols: Vec<SymbolEntry>,
38	    pub(super) blocks: Vec<CodeBlock>,
39	    pub(super) test_blocks: Vec<CodeBlock>,
40	    pub(super) had_parse_errors: bool,
41	    pub(super) degradation: Option<Degradation>,
42	}
43	
44	impl Extraction {
45	    /// The result for a file that could not be analyzed: no data, flagged as having errors and the reason.
46	    fn degraded(degradation: Degradation) -> Self {
47	        Self { had_parse_errors: true, degradation: Some(degradation), ..Self::default() }
48	    }
49	}
50	
51	/// Extracts what `profile` asks for from `source`.
52	///
53	/// Rust files have no dependency records, so the dependencies profile reads nothing. A file too long or nested too
54	/// deeply for the parse stack and the tree drop is [`Extraction::degraded`] without being parsed, and so is one whose
55	/// parse or extraction panics.
56	pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
57	    if profile == AnalysisProfile::Dependencies {
58	        return Extraction::default();
59	    }
60	    if source.len() > MAX_PARSED_SOURCE_LEN {
61	        return Extraction::degraded(Degradation::TooLarge { bytes: source.len(), cap: MAX_PARSED_SOURCE_LEN });
62	    }
63	    if let Err(degradation) = nesting::check(source, Syntax::Rust, MAX_NESTING_LEVELS) {
64	        return Extraction::degraded(degradation);
65	    }
66	    on_parse_stack(|| parse_and_extract(path, source, profile)).unwrap_or_else(Extraction::degraded)
67	}
68	
69	fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
70	    let parse = SourceFile::parse(source, Edition::CURRENT);
71	    let had_parse_errors = !parse.errors().is_empty();
72	    // The root of a parse is always a source file, so the cast cannot fail; the let-else keeps that out of a panic.
73	    let Some(file) = SourceFile::cast(parse.syntax_node()) else {
74	        return Extraction::degraded(Degradation::Panicked);
75	    };
76	    let mut walker = Walker { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
77	    let file_is_test = file.attrs().any(|attr| attr.excl_token().is_some() && is_test_attr(&attr));
78	    walker.items(file.items(), None, file_is_test);
79	    Extraction { had_parse_errors, ..walker.out }
80	}
81	
82	/// Parses and extracts on the calling thread, for a test that supplies its own stack.
83	#[cfg(all(test, feature = "lang-ts"))]
84	pub(super) fn parse_here(source: &str) {
85	    drop(parse_and_extract(Utf8Path::new("a.rs"), source, AnalysisProfile::Full));
86	}
87	
88	/// Maps byte offsets to 1-based line numbers.
89	struct LineIndex {
90	    newlines: Vec<u32>,
91	}
92	
93	impl LineIndex {
94	    fn new(source: &str) -> Self {
95	        Self {
96	            newlines: source
97	                .bytes()
98	                .enumerate()
99	                .filter(|&(_, byte)| byte == b'\n')
100	                .filter_map(|(offset, _)| u32::try_from(offset).ok())
101	                .collect(),
102	        }
103	    }
104	
105	    fn line(&self, offset: u32) -> usize {
106	        self.newlines.partition_point(|&newline| newline < offset) + 1
107	    }
108	}
109	
110	/// The item whose members are being walked: what each member block takes as its parent.
111	struct Holder {
112	    parent: ParentContext,
113	    /// The type that owns the members: an `impl`'s target or a trait's name; `None` for a module.
114	    owner: Option<String>,
115	    /// The trait an `impl` implements.
116	    trait_impl: Option<String>,
117	}
118	
119	/// An item or method as the walk found it.
120	struct Declared<'a> {
121	    node: &'a SyntaxNode,
122	    kind: SymbolKind,
123	    /// `None` for an item that has no name (a macro call, an `extern` block) or that the parse recovered without one.
124	    name: Option<&'a str>,
125	    visibility: Option<ast::Visibility>,
126	}
127	
128	struct Walker<'s> {
129	    path: &'s Utf8Path,
130	    source: &'s str,
131	    profile: AnalysisProfile,
132	    lines: LineIndex,
133	    out: Extraction,
134	}
135	
136	impl Walker<'_> {
137	    fn text(&self, range: TextRange) -> &str {
138	        self.source.get(usize::from(range.start())..usize::from(range.end())).unwrap_or_default()
139	    }
140	
141	    fn line_of(&self, offset: ra_ap_syntax::TextSize) -> usize {
142	        self.lines.line(u32::from(offset))
143	    }
144	
145	    /// Walks the items of a file or an inline module. Each becomes a block, then its own members do. `in_test` marks
146	    /// the items as test code when an enclosing item or file is.
147	    fn items(&mut self, items: impl Iterator<Item = ast::Item>, holder: Option<&Holder>, in_test: bool) {
148	        for item in items {
149	            self.item(&item, holder, in_test);
150	        }
151	    }
152	
153	    fn item(&mut self, item: &ast::Item, holder: Option<&Holder>, in_test: bool) {
154	        let Some((kind, name)) = describe(item) else { return };
155	        let in_test = in_test || item.attrs().any(|attr| is_test_attr(&attr));
156	        let declared = Declared { node: item.syntax(), kind, name: name.as_deref(), visibility: item_visibility(item) };
157	        self.record(&declared, holder, in_test);
158	
159	        let Some(name) = name else { return };
160	        let line = self.line_of(item.syntax().text_range().start());
161	        match item {
162	            ast::Item::Module(module) => {
163	                let Some(list) = module.item_list() else { return };
164	                let holder = Holder { parent: ParentContext { kind, name, line }, owner: None, trait_impl: None };
165	                self.items(list.items(), Some(&holder), in_test);
166	            }
167	            ast::Item::Impl(imp) => {
168	                let trait_impl = imp.trait_().map(|ty| collapse(&ty.syntax().text().to_string()));
169	                let owner = imp.self_ty().map(|ty| collapse(&ty.syntax().text().to_string()));
170	                let holder = Holder { parent: ParentContext { kind, name, line }, owner, trait_impl };
171	                self.methods(imp.assoc_item_list(), &holder, in_test);
172	            }
173	            ast::Item::Trait(item_trait) => {
174	                let holder =
175	                    Holder { owner: Some(name.clone()), parent: ParentContext { kind, name, line }, trait_impl: None };
176	                self.methods(item_trait.assoc_item_list(), &holder, in_test);
177	            }
178	            ast::Item::AsmExpr(_)
179	            | ast::Item::Const(_)
180	            | ast::Item::Enum(_)
181	            | ast::Item::ExternBlock(_)
182	            | ast::Item::ExternCrate(_)
183	            | ast::Item::Fn(_)
184	            | ast::Item::MacroCall(_)
185	            | ast::Item::MacroDef(_)
186	            | ast::Item::MacroRules(_)
187	            | ast::Item::Static(_)
188	            | ast::Item::Struct(_)
189	            | ast::Item::TypeAlias(_)
190	            | ast::Item::Union(_)
191	            | ast::Item::Use(_) => {}
192	        }
193	    }
194	
195	    /// A block for each method with a body in an `impl` or trait, at least [`MIN_MEMBER_LINES`] long unless it is test
196	    /// code. Any other member (a bodiless method, a constant, a type, a macro call) gets one only when it is itself
197	    /// marked as test code, so its matches do not go to the holder.
198	    fn methods(&mut self, list: Option<ast::AssocItemList>, holder: &Holder, in_test: bool) {
199	        let Some(list) = list else { return };
200	        for member in list.assoc_items() {
201	            let marked = member.attrs().any(|attr| is_test_attr(&attr));
202	            let (kind, name, visibility, node) = match &member {
203	                ast::AssocItem::Fn(function) if function.body().is_some() => {
204	                    let Some(name) = function.name() else { continue };
205	                    let in_test = in_test || marked;
206	                    let range = function.syntax().text_range();
207	                    // A short test method still gets a block, so a search can tell its matches from the holder's.
208	                    if !in_test && self.line_of(range.end()) - self.line_of(range.start()) + 1 < MIN_MEMBER_LINES {
209	                        continue;
210	                    }
211	                    let declared = Declared {
212	                        node: function.syntax(),
213	                        kind: SymbolKind::Method,
214	                        name: Some(name.text()),
215	                        visibility: function.visibility(),
216	                    };
217	                    self.record(&declared, Some(holder), in_test);
218	                    continue;
219	                }
220	                ast::AssocItem::Fn(function) => {
221	                    (SymbolKind::Method, function.name(), function.visibility(), function.syntax())
222	                }
223	                ast::AssocItem::Const(item) => (SymbolKind::Variable, item.name(), item.visibility(), item.syntax()),
224	                ast::AssocItem::TypeAlias(item) => {
225	                    (SymbolKind::TypeAlias, item.name(), item.visibility(), item.syntax())
226	                }
227	                ast::AssocItem::MacroCall(call) => (SymbolKind::Macro, None, None, call.syntax()),
228	            };
229	            if marked {
230	                let declared = Declared { node, kind, name: name.as_ref().map(ast::Name::text), visibility };
231	                self.record(&declared, Some(holder), true);
232	            }
233	        }
234	    }
235	
236	    /// Records one item: its symbol unless it is test code, and its block, with attributes and doc comments, under the
237	    /// full profile. `name` is `None` for an item without one, which leaves it without a symbol.
238	    fn record(&mut self, declared: &Declared<'_>, holder: Option<&Holder>, in_test: bool) {
239	        let Declared { node, kind, name, ref visibility } = *declared;
240	        let signature = self.signature(node);
241	        let range = node.text_range();
242	        let (line_start, line_end) = (self.line_of(range.start()), self.line_of(range.end()));
243	        // A trait's methods and the methods implementing one are as visible as the trait, which they do not say.
244	        let inherits_visibility =
245	            holder.is_some_and(|h| h.trait_impl.is_some() || h.parent.kind == SymbolKind::Interface);
246	        if let (Some(name), false) = (name, in_test) {
247	            self.out.symbols.push(SymbolEntry {
248	                name: name.to_owned(),
249	                kind,
250	                line: line_start,
251	                signature: Some(signature.clone()),
252	                owner: holder.and_then(|holder| holder.owner.clone()),
253	                trait_impl: holder.and_then(|holder| holder.trait_impl.clone()),
254	                visibility: (!inherits_visibility).then(|| self.visibility(visibility.as_ref())),
255	                kind_detail: None,
256	            });
257	        }
258	        if self.profile != AnalysisProfile::Full {
259	            return;
260	        }
261	        let block = CodeBlock {
262	            file: self.path.to_owned(),
263	            line_start,
264	            line_end,
265	            node_kind: kind,
266	            code: self.text(range).to_owned(),
267	            symbol_signature: Some(signature),
268	            matched_lines: Vec::new(),
269	            matched_keywords: Vec::new(),
270	            parent: holder.map(|holder| holder.parent.clone()),
271	        };
272	        if in_test {
273	            self.out.test_blocks.push(block);
274	        } else {
275	            self.out.blocks.push(block);
276	        }
277	    }
278	
279	    /// The item's header on one line: everything from its visibility or first keyword up to its body or initializer,
280	    /// without attributes and doc comments. `pub fn f<T>(a: &str) -> T where T: Clone`.
281	    fn signature(&self, node: &SyntaxNode) -> String {
282	        let mut start = None;
283	        let mut end = node.text_range().end();
284	        for element in node.children_with_tokens() {
285	            let kind = element.kind();
286	            if start.is_none() {
287	                if matches!(kind, SyntaxKind::ATTR | SyntaxKind::COMMENT | SyntaxKind::WHITESPACE) {
288	                    continue;
289	                }
290	                start = Some(element.text_range().start());
291	            }
292	            let is_body = match &element {
293	                NodeOrToken::Node(_) => matches!(
294	                    kind,
295	                    SyntaxKind::BLOCK_EXPR
296	                        | SyntaxKind::RECORD_FIELD_LIST
297	                        | SyntaxKind::VARIANT_LIST
298	                        | SyntaxKind::ASSOC_ITEM_LIST
299	                        | SyntaxKind::ITEM_LIST
300	                        | SyntaxKind::EXTERN_ITEM_LIST
301	                        | SyntaxKind::TOKEN_TREE
302	                ),
303	                NodeOrToken::Token(_) => kind == SyntaxKind::EQ,
304	            };
305	            if is_body {
306	                end = element.text_range().start();
307	                break;
308	            }
309	        }
310	        let Some(start) = start else { return String::new() };
311	        collapse(self.text(TextRange::new(start, end.max(start)))).trim_end_matches([';', ',']).trim_end().to_owned()
312	    }
313	
314	    fn visibility(&self, visibility: Option<&ast::Visibility>) -> Visibility {
315	        let Some(visibility) = visibility else { return Visibility::Private };
316	        let text = collapse(self.text(visibility.syntax().text_range()));
317	        let text = text.replace(' ', "");
318	        match text.as_str() {
319	            "pub" => Visibility::Public,
320	            "pub(crate)" => Visibility::Crate,
321	            _ => Visibility::Module,
322	        }
323	    }
324	}
325	
326	/// The kind and the name of an item that gets a block, `None` for one that does not (a `use`, an `extern crate`, an
327	/// out-of-line module). The name is `None` for an item that has none (a macro call, an `extern` block) or that the parse
328	/// recovered without one.
329	fn describe(item: &ast::Item) -> Option<(SymbolKind, Option<String>)> {
330	    let named = |name: Option<ast::Name>| name.map(|name| name.text().to_owned());
331	    Some(match item {
332	        ast::Item::Fn(it) => (SymbolKind::Function, named(it.name())),
333	        ast::Item::Struct(it) => (SymbolKind::Struct, named(it.name())),
334	        ast::Item::Union(it) => (SymbolKind::Struct, named(it.name())),
335	        ast::Item::Enum(it) => (SymbolKind::Enum, named(it.name())),
336	        ast::Item::Trait(it) => (SymbolKind::Interface, named(it.name())),
337	        ast::Item::TypeAlias(it) => (SymbolKind::TypeAlias, named(it.name())),
338	        ast::Item::Const(it) => (SymbolKind::Variable, named(it.name())),
339	        ast::Item::Static(it) => (SymbolKind::Variable, named(it.name())),
340	        ast::Item::MacroRules(it) => (SymbolKind::Macro, named(it.name())),

340	        ast::Item::MacroRules(it) => (SymbolKind::Macro, named(it.name())),
341	        ast::Item::MacroDef(it) => (SymbolKind::Macro, named(it.name())),
342	        // A module declared in another file has no body to split.
343	        ast::Item::Module(it) => (it.item_list().is_some()).then(|| (SymbolKind::Module, named(it.name())))?,
344	        ast::Item::Impl(it) => {
345	            let target = it.self_ty().map(|ty| collapse(&ty.syntax().text().to_string()));
346	            let name = match (it.trait_(), target) {
347	                (Some(implemented), Some(target)) => {
348	                    Some(format!("{} for {target}", collapse(&implemented.syntax().text().to_string())))
349	                }
350	                (None, target) => target,
351	                (Some(_), None) => None,
352	            };
353	            (SymbolKind::Impl, name)
354	        }
355	        // These declare no name of their own, but what they hold (`thread_local!`'s statics, an `extern` block's
356	        // functions) is searchable only through a block.
357	        ast::Item::MacroCall(_) => (SymbolKind::Macro, None),
358	        ast::Item::ExternBlock(_) => (SymbolKind::Other, None),
359	        ast::Item::AsmExpr(_) | ast::Item::ExternCrate(_) | ast::Item::Use(_) => return None,
360	    })
361	}
362	
363	fn item_visibility(item: &ast::Item) -> Option<ast::Visibility> {
364	    match item {
365	        ast::Item::Fn(it) => it.visibility(),
366	        ast::Item::Struct(it) => it.visibility(),
367	        ast::Item::Union(it) => it.visibility(),
368	        ast::Item::Enum(it) => it.visibility(),
369	        ast::Item::Trait(it) => it.visibility(),
370	        ast::Item::TypeAlias(it) => it.visibility(),
371	        ast::Item::Const(it) => it.visibility(),
372	        ast::Item::Static(it) => it.visibility(),
373	        ast::Item::Module(it) => it.visibility(),
374	        ast::Item::MacroDef(it) => it.visibility(),
375	        ast::Item::Impl(it) => it.visibility(),
376	        ast::Item::MacroRules(_)
377	        | ast::Item::AsmExpr(_)
378	        | ast::Item::ExternBlock(_)
379	        | ast::Item::ExternCrate(_)
380	        | ast::Item::MacroCall(_)
381	        | ast::Item::Use(_) => None,
382	    }
383	}
384	
385	/// `text` on one line: every run of whitespace becomes one space.
386	fn collapse(text: &str) -> String {
387	    text.split_whitespace().collect::<Vec<_>>().join(" ")
388	}
389	
390	/// Whether an attribute marks the item it decorates as test-only: `#[test]`, `#[tokio::test]`, or a `#[cfg(...)]`
391	/// that holds only when `test` does.
392	fn is_test_attr(attr: &ast::Attr) -> bool {
393	    match attr.meta() {
394	        Some(ast::Meta::CfgMeta(cfg)) => cfg.cfg_predicate().is_some_and(|predicate| implies_test(&predicate)),
395	        Some(ast::Meta::PathMeta(meta)) => meta.path().is_some_and(|path| last_segment_is_test(&path)),
396	        Some(ast::Meta::TokenTreeMeta(meta)) => meta.path().is_some_and(|path| last_segment_is_test(&path)),
397	        Some(ast::Meta::CfgAttrMeta(_) | ast::Meta::KeyValueMeta(_) | ast::Meta::UnsafeMeta(_)) | None => false,
398	    }
399	}
400	
401	fn last_segment_is_test(path: &ast::Path) -> bool {
402	    path.segment().and_then(|segment| segment.name_ref()).is_some_and(|name| name.text() == "test")
403	}
404	
405	/// Whether a `cfg` predicate can only hold in a test build: `test`, an `all` with such a part, or an `any` of only such
406	/// parts. A `not` never does.
407	fn implies_test(predicate: &ast::CfgPredicate) -> bool {
408	    match predicate {
409	        ast::CfgPredicate::CfgAtom(atom) => {
410	            atom.eq_token().is_none() && atom.ident_token().is_some_and(|ident| ident.text() == "test")
411	        }
412	        ast::CfgPredicate::CfgComposite(composite) => {
413	            let keyword = composite.keyword();
414	            let mut parts = composite.cfg_predicates();
415	            match keyword.as_ref().map(ra_ap_syntax::SyntaxToken::text) {
416	                Some("all") => parts.any(|part| implies_test(&part)),
417	                Some("any") => {
418	                    let parts: Vec<_> = parts.collect();
419	                    !parts.is_empty() && parts.iter().all(implies_test)
420	                }
421	                _ => false,
422	            }
423	        }
424	    }
425	}
426	
427	#[cfg(test)]
428	mod tests {
429	    use super::*;
430	
431	    #[test]
432	    fn line_numbers_are_one_based_and_count_preceding_newlines() {
433	        let index = LineIndex::new("a\nbb\n\nc");
434	        assert_eq!([0, 1, 2, 4, 5, 6].map(|offset| index.line(offset)), [1, 1, 2, 2, 3, 4]);
435	    }
436	}
