80	pub(super) fn parse_here(source: &str) {
81	    drop(parse_and_extract(Utf8Path::new("a.rs"), source));
82	}
83	
84	/// Maps byte offsets to 1-based line numbers.
85	struct LineIndex {
86	    newlines: Vec<u32>,
87	}
88	
89	impl LineIndex {
90	    fn new(source: &str) -> Self {
91	        Self {
92	            newlines: source
93	                .bytes()
94	                .enumerate()
95	                .filter(|&(_, byte)| byte == b'\n')
96	                .filter_map(|(offset, _)| u32::try_from(offset).ok())
97	                .collect(),
98	        }
99	    }
100	
101	    fn line(&self, offset: u32) -> usize {
102	        self.newlines.partition_point(|&newline| newline < offset) + 1
103	    }
104	}
105	
106	/// An item or method as the walk found it.
107	struct Declared<'a> {
108	    node: &'a SyntaxNode,
109	    kind: SymbolKind,
110	    /// `None` for an item that has no name (a macro call, an `extern` block) or that the parse recovered without one.
111	    name: Option<&'a str>,
112	}
113	
114	struct Walker<'s> {
115	    path: &'s Utf8Path,
116	    source: &'s str,
117	    lines: LineIndex,
118	    out: Extraction,
119	}
120	
121	impl Walker<'_> {
122	    fn text(&self, range: TextRange) -> &str {
123	        self.source.get(usize::from(range.start())..usize::from(range.end())).unwrap_or_default()
124	    }
125	
126	    fn line_of(&self, offset: ra_ap_syntax::TextSize) -> usize {
127	        self.lines.line(u32::from(offset))
128	    }
129	
130	    /// Walks the items of a file or an inline module. Each becomes a block, then its own members do. `in_test` marks
131	    /// the items as test code when an enclosing item or file is.
132	    fn items(&mut self, items: impl Iterator<Item = ast::Item>, holder: Option<&ParentContext>, in_test: bool) {
133	        for item in items {
134	            self.item(&item, holder, in_test);
135	        }
136	    }
137	
138	    fn item(&mut self, item: &ast::Item, holder: Option<&ParentContext>, in_test: bool) {
139	        let Some((kind, name)) = describe(item) else { return };
140	        let in_test = in_test || item.attrs().any(|attr| is_test_attr(&attr));
141	        let declared = Declared { node: item.syntax(), kind, name: name.as_deref() };
142	        self.record(&declared, holder, in_test);
143	
144	        let Some(name) = name else { return };
145	        let holder = ParentContext { kind, name };
146	        match item {
147	            ast::Item::Module(module) => {
148	                let Some(list) = module.item_list() else { return };
149	                self.items(list.items(), Some(&holder), in_test);
150	            }
151	            ast::Item::Impl(imp) => self.methods(imp.assoc_item_list(), &holder, in_test),
152	            ast::Item::Trait(item_trait) => self.methods(item_trait.assoc_item_list(), &holder, in_test),
153	            ast::Item::AsmExpr(_)
154	            | ast::Item::Const(_)
155	            | ast::Item::Enum(_)
156	            | ast::Item::ExternBlock(_)
157	            | ast::Item::ExternCrate(_)
158	            | ast::Item::Fn(_)
159	            | ast::Item::MacroCall(_)
160	            | ast::Item::MacroDef(_)
161	            | ast::Item::MacroRules(_)
162	            | ast::Item::Static(_)
163	            | ast::Item::Struct(_)
164	            | ast::Item::TypeAlias(_)
165	            | ast::Item::Union(_)
166	            | ast::Item::Use(_) => {}
167	        }
168	    }
169	
170	    /// A block for each method with a body in an `impl` or trait, at least [`MIN_MEMBER_LINES`] long unless it is test
171	    /// code. Any other member (a bodiless method, a constant, a type, a macro call) gets one only when it is itself
172	    /// marked as test code, so its matches do not go to the holder.
173	    fn methods(&mut self, list: Option<ast::AssocItemList>, holder: &ParentContext, in_test: bool) {
174	        let Some(list) = list else { return };
175	        for member in list.assoc_items() {
176	            let marked = member.attrs().any(|attr| is_test_attr(&attr));
177	            let (kind, name, node) = match &member {
178	                ast::AssocItem::Fn(function) if function.body().is_some() => {
