1008	    type Shape = (&'static str, &'static str, Box<dyn Fn(usize) -> String>);
1009	
1010	    /// The ways TypeScript nests that the parser and the extractor recurse over, each as a path and a function of its
1011	    /// depth. Every one of these was measured to cost at most 1.7 KB of stack per unit of the nesting estimate in a build
1012	    /// without optimizations, which is what the fixed stack is sized from.
1013	    fn shapes() -> Vec<Shape> {
1014	        let shape = |name, path, text: fn(usize) -> String| -> Shape { (name, path, Box::new(text)) };
1015	        vec![
1016	            shape("arrays", "a.ts", |d| expr(d, "[", "1", "]")),
1017	            shape("parentheses", "a.ts", |d| expr(d, "(", "1", ")")),

1060	
1061	    /// The deepest `depth` for which `text(depth)` is nested within the cap.
1062	    fn deepest_accepted(path: &str, text: &dyn Fn(usize) -> String) -> usize {
1063	        let syntax = nesting::Syntax::TypeScript { jsx: path.ends_with('x') };
1064	        let accepted = |depth: usize| nesting::check(&text(depth), syntax, parse::MAX_NESTING_LEVELS).is_ok();
1065	        let (mut accepted_depth, mut rejected_depth) = (1, 16 * parse::MAX_NESTING_LEVELS);
1066	        assert!(accepted(accepted_depth) && !accepted(rejected_depth));
1067	        while rejected_depth - accepted_depth > 1 {
1068	            let middle = usize::midpoint(accepted_depth, rejected_depth);
1069	            if accepted(middle) {
1070	                accepted_depth = middle;
1071	            } else {
1072	                rejected_depth = middle;
1073	            }
1074	        }
1075	        accepted_depth
1076	    }
1077	
1078	    /// Every shape at the deepest depth the estimate accepts runs through the real parser and extractor on the fixed
1079	    /// stack. A stack that is too small aborts the test process, so this passing is the safety factor holding in an
1080	    /// unoptimized build, which uses the most stack per level.
1081	    #[test]
1082	    fn every_shape_at_the_cap_is_parsed_on_the_fixed_stack() {
1083	        for (name, path, text) in shapes() {
1084	            let depth = deepest_accepted(path, &*text);
1085	            let analysis = analyze_source(path, &text(depth), AnalysisProfile::Full);
1086	            assert_eq!(analysis.degradation, None, "{name} at depth {depth}");
1087	            assert!(!analysis.had_parse_errors, "{name} at depth {depth}");
1088	        }
1089	    }
